use std::sync::mpsc::{sync_channel, Receiver, SyncSender};
use std::sync::{Arc, Mutex};
use std::thread;

fn sender(ch: SyncSender<usize>, m: Arc<Mutex<usize>>) {
    for value in [1, 2] {
        {
            let mut count = m.lock().unwrap();
            *count += 1;
        } // Release m before sending, which may wait.
        ch.send(value).unwrap();
    }
}

fn receiver(ch: Receiver<usize>, m: Arc<Mutex<usize>>) {
    for _ in 0..2 {
        {
            let mut count = m.lock().unwrap();
            *count += 1;
        } // Release m before receiving, which may wait.
        let _value = ch.recv().unwrap();
    }
}

fn main() {
    let ch = sync_channel(1);
    let (tx, rx) = ch;
    let m = Arc::new(Mutex::new(0));

    let sender_thread = {
        let m = Arc::clone(&m);
        thread::spawn(move || sender(tx, m))
    };
    let receiver_thread = thread::spawn(move || receiver(rx, m));

    sender_thread.join().unwrap();
    receiver_thread.join().unwrap();

    println!("DONE done=1");
}
